using System.Text.Json;
using CustSearch.Application.Authentication;
using CustSearch.Application.Authorization;
using CustSearch.Application.Recognition;
using CustSearch.Application.TenantOperations;
using CustSearch.Domain.Entities;
using CustSearch.Domain.Enums;
using CustSearch.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Options;

namespace CustSearch.Infrastructure.Recognition;

/// <summary>Enforces consent, tenant/store isolation, encrypted enrollment, retention and human review.</summary>
/// <summary>
/// Manages consent-gated enrollment and human review of recognition candidates. It never performs
/// cross-tenant matching and withdrawal prevents continued use of protected biometric templates.
/// </summary>
public sealed class RecognitionService(CustSearchDbContext db,ICurrentUserContext currentUser,IRecognitionTemplateProtector protector,TimeProvider clock,IOptions<RecognitionSecurityOptions>options):IRecognitionService
{
    private static readonly JsonSerializerOptions AuditJson=new(JsonSerializerDefaults.Web);private readonly RecognitionSecurityOptions security=options.Value;
    public async Task<IReadOnlyList<RecognitionConsentView>>ListConsentsAsync(long customerId,CancellationToken ct=default){RequirePermission(PermissionCatalog.Operations.RecognitionView);var tenant=RequireTenant();await RequireCustomer(tenant,customerId,null,ct).ConfigureAwait(false);var now=clock.GetUtcNow().UtcDateTime;return await db.CustomerRecognitionConsents.AsNoTracking().Where(x=>x.TenantId==tenant&&x.CustomerId==customerId).OrderByDescending(x=>x.GrantedUtc).Select(x=>new RecognitionConsentView(x.Id,x.CustomerId,x.ConsentType,x.Purpose,x.GrantedUtc,x.ExpiresUtc,x.WithdrawnUtc,x.ConsentVersion,x.CapturedByUserId,x.EvidenceReference,x.WithdrawnUtc==null&&x.GrantedUtc<=now&&(x.ExpiresUtc==null||x.ExpiresUtc>now))).ToListAsync(ct).ConfigureAwait(false);}
    public async Task<RecognitionConsentView>GrantConsentAsync(long customerId,GrantRecognitionConsentCommand command,TenantAuditContext audit,CancellationToken ct=default)
    {RequirePermission(PermissionCatalog.Operations.RecognitionConsentManage);ArgumentNullException.ThrowIfNull(command);ArgumentNullException.ThrowIfNull(audit);var tenant=RequireTenant();await RequireCustomer(tenant,customerId,null,ct).ConfigureAwait(false);var now=clock.GetUtcNow().UtcDateTime;if(command.GrantedUtc>now.AddMinutes(5))throw Failure("Consent cannot be granted in the future.");var purpose=command.Purpose.Trim();var duplicate=await db.CustomerRecognitionConsents.AnyAsync(x=>x.TenantId==tenant&&x.CustomerId==customerId&&x.ConsentType==command.ConsentType&&x.Purpose==purpose&&x.WithdrawnUtc==null&&(x.ExpiresUtc==null||x.ExpiresUtc>now),ct).ConfigureAwait(false);if(duplicate)throw Failure("An active consent already exists for this purpose.",RecognitionFailureKind.Conflict);CustomerRecognitionConsent consent;try{consent=CustomerRecognitionConsent.Grant(tenant,customerId,command.ConsentType,purpose,command.GrantedUtc,command.ExpiresUtc,command.ConsentVersion,audit.ActorUserId,command.EvidenceReference);}catch(ArgumentException ex){throw Failure(ex.Message);}db.CustomerRecognitionConsents.Add(consent);await db.SaveChangesAsync(ct).ConfigureAwait(false);Audit(audit,tenant,null,"RecognitionConsentGranted","CustomerRecognitionConsent",consent.Id,new{consent.Id,consent.CustomerId,consent.ConsentType,consent.Purpose,consent.GrantedUtc,consent.ExpiresUtc,consent.ConsentVersion,HasEvidence=consent.EvidenceReference!=null},now);await db.SaveChangesAsync(ct).ConfigureAwait(false);return Map(consent,now);}
    public async Task<RecognitionConsentView>WithdrawConsentAsync(long consentId,string reason,TenantAuditContext audit,CancellationToken ct=default)
    {RequirePermission(PermissionCatalog.Operations.RecognitionConsentManage);ArgumentException.ThrowIfNullOrWhiteSpace(reason);ArgumentNullException.ThrowIfNull(audit);var tenant=RequireTenant();var consent=await db.CustomerRecognitionConsents.SingleOrDefaultAsync(x=>x.Id==consentId&&x.TenantId==tenant,ct).ConfigureAwait(false)??throw Failure("Consent was not found.",RecognitionFailureKind.NotFound);await RequireCustomer(tenant,consent.CustomerId,null,ct).ConfigureAwait(false);var now=clock.GetUtcNow().UtcDateTime;await using var transaction=await db.Database.BeginTransactionAsync(ct).ConfigureAwait(false);try{consent.Withdraw(now);}catch(InvalidOperationException ex){throw Failure(ex.Message,RecognitionFailureKind.Conflict);}var templates=await db.BiometricTemplates.Where(x=>x.TenantId==tenant&&x.ConsentId==consent.Id&&x.Status==BiometricTemplateStatus.Active).ToListAsync(ct).ConfigureAwait(false);foreach(var template in templates)template.DisableAndErase(now,now.AddDays(security.RetentionDaysAfterWithdrawal));Audit(audit,tenant,null,"RecognitionConsentWithdrawn","CustomerRecognitionConsent",consent.Id,new{consent.Id,Reason=reason.Trim(),ErasedTemplates=templates.Count,RetentionDays=security.RetentionDaysAfterWithdrawal},now);await db.SaveChangesAsync(ct).ConfigureAwait(false);await transaction.CommitAsync(ct).ConfigureAwait(false);return Map(consent,now);}
    public async Task<IReadOnlyList<BiometricTemplateView>>ListTemplatesAsync(long customerId,TenantAuditContext audit,CancellationToken ct=default)
    {RequirePermission(PermissionCatalog.Operations.RecognitionView);ArgumentNullException.ThrowIfNull(audit);var tenant=RequireTenant();await RequireCustomer(tenant,customerId,null,ct).ConfigureAwait(false);var query=db.BiometricTemplates.AsNoTracking().Where(x=>x.TenantId==tenant&&x.CustomerId==customerId);if(!TenantWide())query=query.Where(x=>currentUser.StoreIds.Contains(x.StoreId));var templates=await query.OrderByDescending(x=>x.CreatedUtc).Select(x=>new BiometricTemplateView(x.Id,x.StoreId,x.CustomerId,x.ConsentId,x.Algorithm,x.TemplateVersion,x.Status,x.CreatedUtc,x.DisabledUtc,x.DeletedUtc,x.RetentionUntilUtc)).ToListAsync(ct).ConfigureAwait(false);Audit(audit,tenant,null,"BiometricTemplateMetadataViewed","Customer",customerId,new{CustomerId=customerId,TemplateCount=templates.Count},clock.GetUtcNow().UtcDateTime);await db.SaveChangesAsync(ct).ConfigureAwait(false);return templates;}
    public async Task<BiometricTemplateView>EnrollAsync(long customerId,EnrollBiometricTemplateCommand command,TenantAuditContext audit,CancellationToken ct=default)
    {RequirePermission(PermissionCatalog.Operations.RecognitionEnroll);ArgumentNullException.ThrowIfNull(command);ArgumentNullException.ThrowIfNull(audit);if(!security.Enabled)throw Failure("Recognition is disabled until encryption and policy configuration are explicitly enabled.",RecognitionFailureKind.Unavailable);var tenant=RequireTenant();RequireStore(command.StoreId);await RequireCustomer(tenant,customerId,command.StoreId,ct).ConfigureAwait(false);var now=clock.GetUtcNow().UtcDateTime;var consent=await db.CustomerRecognitionConsents.SingleOrDefaultAsync(x=>x.Id==command.ConsentId&&x.TenantId==tenant&&x.CustomerId==customerId,ct).ConfigureAwait(false)??throw Failure("Consent was not found.",RecognitionFailureKind.NotFound);if(!consent.IsActiveAt(now)||!string.Equals(consent.Purpose,command.Purpose.Trim(),StringComparison.Ordinal))throw Failure("Active purpose-matching consent is required for enrollment.",RecognitionFailureKind.Forbidden);byte[]derived;try{derived=Convert.FromBase64String(command.DerivedTemplateBase64);}catch(FormatException){throw Failure("Derived template is not valid Base64.");}ProtectedRecognitionTemplate protectedTemplate;try{protectedTemplate=protector.Protect(derived);}finally{System.Security.Cryptography.CryptographicOperations.ZeroMemory(derived);}var template=BiometricTemplate.Enroll(tenant,command.StoreId,customerId,consent.Id,protectedTemplate.Ciphertext,protectedTemplate.Nonce,protectedTemplate.AuthenticationTag,protectedTemplate.KeyReference,protectedTemplate.Algorithm,command.TemplateVersion,now);await using var transaction=await db.Database.BeginTransactionAsync(ct).ConfigureAwait(false);var existing=await db.BiometricTemplates.Where(x=>x.TenantId==tenant&&x.StoreId==command.StoreId&&x.CustomerId==customerId&&x.Status==BiometricTemplateStatus.Active).ToListAsync(ct).ConfigureAwait(false);foreach(var active in existing)active.DisableAndErase(now,now.AddDays(security.RetentionDaysAfterWithdrawal));db.BiometricTemplates.Add(template);await db.SaveChangesAsync(ct).ConfigureAwait(false);Audit(audit,tenant,command.StoreId,"BiometricTemplateEnrolled","BiometricTemplate",template.Id,new{template.CustomerId,template.StoreId,template.ConsentId,template.Algorithm,template.TemplateVersion,ReplacedTemplates=existing.Count},now);await db.SaveChangesAsync(ct).ConfigureAwait(false);await transaction.CommitAsync(ct).ConfigureAwait(false);return Map(template);}
    public async Task<RecognitionCandidateView>CreateCandidateAsync(CreateRecognitionCandidateCommand command,TenantAuditContext audit,CancellationToken ct=default)
    {RequirePermission(PermissionCatalog.Operations.RecognitionSettingsManage);ArgumentNullException.ThrowIfNull(command);ArgumentNullException.ThrowIfNull(audit);if(!security.Enabled)throw Failure("Recognition is disabled.",RecognitionFailureKind.Unavailable);var tenant=RequireTenant();RequireStore(command.StoreId);var existing=await db.RecognitionCandidates.AsNoTracking().SingleOrDefaultAsync(x=>x.TenantId==tenant&&x.StoreId==command.StoreId&&x.RequestId==command.RequestId,ct).ConfigureAwait(false);if(existing is not null){if(existing.PersonTrackSessionId!=command.PersonTrackSessionId||existing.BiometricTemplateId!=command.BiometricTemplateId)throw Failure("Recognition request id was already used for different input.",RecognitionFailureKind.Conflict);return Map(existing);}var track=await db.PersonTrackSessions.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==command.PersonTrackSessionId&&x.TenantId==tenant&&x.StoreId==command.StoreId,ct).ConfigureAwait(false)??throw Failure("Anonymous track was not found.",RecognitionFailureKind.NotFound);if(track.SubjectKind!=TrackingSubjectKind.Anonymous)throw Failure("Recognition candidates can only reference an anonymous track; identity is never overwritten.",RecognitionFailureKind.Conflict);var template=await db.BiometricTemplates.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==command.BiometricTemplateId&&x.TenantId==tenant&&x.StoreId==command.StoreId&&x.Status==BiometricTemplateStatus.Active,ct).ConfigureAwait(false)??throw Failure("Active biometric template was not found in this store.",RecognitionFailureKind.NotFound);var now=clock.GetUtcNow().UtcDateTime;var consent=await db.CustomerRecognitionConsents.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==template.ConsentId&&x.TenantId==tenant&&x.CustomerId==template.CustomerId,ct).ConfigureAwait(false);if(consent is null||!consent.IsActiveAt(now)||!string.Equals(consent.Purpose,command.Purpose.Trim(),StringComparison.Ordinal))throw Failure("Recognition requires active purpose-matching consent.",RecognitionFailureKind.Forbidden);var ambiguous=command.SecondBestConfidence.HasValue&&command.Confidence-command.SecondBestConfidence.Value<=security.AmbiguityDelta;var threshold=command.Confidence<security.MinimumConfidence||command.Quality<security.MinimumQuality;var status=ambiguous?RecognitionCandidateStatus.Ambiguous:RecognitionCandidateStatus.PendingReview;var reviewReason=ambiguous?"Ambiguous candidates require human review.":threshold?"Below configured confidence or quality threshold; human review required.":"Human review required before any customer association.";RecognitionCandidate candidate;try{candidate=RecognitionCandidate.Create(tenant,command.StoreId,track.Id,template.Id,template.CustomerId,command.RequestId,command.Purpose,command.Confidence,command.Quality,command.SecondBestConfidence,status,reviewReason,now);}catch(ArgumentException ex){throw Failure(ex.Message);}await using var transaction=await db.Database.BeginTransactionAsync(ct).ConfigureAwait(false);db.RecognitionCandidates.Add(candidate);await db.SaveChangesAsync(ct).ConfigureAwait(false);Audit(audit,tenant,command.StoreId,"RecognitionCandidateCreated","RecognitionCandidate",candidate.Id,new{candidate.RequestId,candidate.PersonTrackSessionId,candidate.CustomerId,candidate.Confidence,candidate.Quality,candidate.Status},now);await db.SaveChangesAsync(ct).ConfigureAwait(false);await transaction.CommitAsync(ct).ConfigureAwait(false);return Map(candidate);}
    public async Task<IReadOnlyList<RecognitionCandidateView>>ListCandidatesAsync(long?storeId,RecognitionCandidateStatus?status,CancellationToken ct=default){RequirePermission(PermissionCatalog.Operations.RecognitionView);var tenant=RequireTenant();if(storeId.HasValue)RequireStore(storeId.Value);var query=db.RecognitionCandidates.AsNoTracking().Where(x=>x.TenantId==tenant);if(storeId.HasValue)query=query.Where(x=>x.StoreId==storeId.Value);else if(!TenantWide())query=query.Where(x=>currentUser.StoreIds.Contains(x.StoreId));if(status.HasValue)query=query.Where(x=>x.Status==status.Value);return await query.OrderByDescending(x=>x.CreatedUtc).Take(500).Select(x=>new RecognitionCandidateView(x.Id,x.StoreId,x.PersonTrackSessionId,x.BiometricTemplateId,x.CustomerId,x.RequestId,x.Purpose,x.Confidence,x.Quality,x.SecondBestConfidence,x.Status,x.CreatedUtc,x.ReviewedUtc,x.ReviewedByUserId,x.ReviewReason)).ToListAsync(ct).ConfigureAwait(false);}
    public async Task<RecognitionCandidateView>ReviewAsync(long candidateId,bool accept,string reason,TenantAuditContext audit,CancellationToken ct=default)
    {RequirePermission(PermissionCatalog.Operations.RecognitionReview);ArgumentException.ThrowIfNullOrWhiteSpace(reason);ArgumentNullException.ThrowIfNull(audit);var tenant=RequireTenant();var candidate=await db.RecognitionCandidates.SingleOrDefaultAsync(x=>x.Id==candidateId&&x.TenantId==tenant,ct).ConfigureAwait(false)??throw Failure("Recognition candidate was not found.",RecognitionFailureKind.NotFound);RequireStore(candidate.StoreId);var template=await db.BiometricTemplates.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==candidate.BiometricTemplateId&&x.TenantId==tenant&&x.StoreId==candidate.StoreId&&x.Status==BiometricTemplateStatus.Active,ct).ConfigureAwait(false);var now=clock.GetUtcNow().UtcDateTime;var consent=template is null?null:await db.CustomerRecognitionConsents.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==template.ConsentId&&x.TenantId==tenant,ct).ConfigureAwait(false);if(template is null||consent is null||!consent.IsActiveAt(now))throw Failure("Candidate cannot be reviewed after consent withdrawal, expiry or template deletion.",RecognitionFailureKind.Forbidden);try{candidate.Review(accept,audit.ActorUserId,reason,now);}catch(InvalidOperationException ex){throw Failure(ex.Message,RecognitionFailureKind.Conflict);}Audit(audit,tenant,candidate.StoreId,accept?"RecognitionCandidateAccepted":"RecognitionCandidateRejected","RecognitionCandidate",candidate.Id,new{candidate.Id,candidate.PersonTrackSessionId,candidate.CustomerId,candidate.Status,Reason=reason.Trim(),TrackAssociationChanged=false},now);await db.SaveChangesAsync(ct).ConfigureAwait(false);return Map(candidate);}
    private long RequireTenant()=>currentUser.TenantId??throw Failure("Tenant scope is required.",RecognitionFailureKind.Forbidden);
    private void RequirePermission(string permission){if(!currentUser.Permissions.Contains(permission))throw Failure("Recognition permission is required.",RecognitionFailureKind.Forbidden);}
    private void RequireStore(long storeId){ArgumentOutOfRangeException.ThrowIfNegativeOrZero(storeId);if(!TenantWide()&&!currentUser.StoreIds.Contains(storeId))throw Failure("Store access is forbidden.",RecognitionFailureKind.Forbidden);}
    private bool TenantWide()=>currentUser.Roles.Any(x=>x is"TenantAdmin"or"TenantOwner"or"ShopOwner");
    private async Task RequireCustomer(long tenant,long customerId,long?storeId,CancellationToken ct){var active=await db.Customers.AnyAsync(x=>x.Id==customerId&&x.TenantId==tenant&&x.IsActive,ct).ConfigureAwait(false);if(!active)throw Failure("Customer was not found.",RecognitionFailureKind.NotFound);if(storeId.HasValue){var assigned=await db.CustomerStoreAssignments.AnyAsync(x=>x.TenantId==tenant&&x.CustomerId==customerId&&x.StoreId==storeId.Value,ct).ConfigureAwait(false);if(!assigned)throw Failure("Customer is not assigned to this store.",RecognitionFailureKind.Forbidden);}else if(!TenantWide()){var visible=await db.CustomerStoreAssignments.AnyAsync(x=>x.TenantId==tenant&&x.CustomerId==customerId&&currentUser.StoreIds.Contains(x.StoreId),ct).ConfigureAwait(false);if(!visible)throw Failure("Customer access is forbidden.",RecognitionFailureKind.Forbidden);}}
    private void Audit(TenantAuditContext audit,long tenant,long?store,string action,string entity,long entityId,object after,DateTime now)=>db.AuditLogs.Add(AuditLog.Record(tenant,store,audit.ActorUserId,"TenantUser",action,entity,entityId.ToString(System.Globalization.CultureInfo.InvariantCulture),null,JsonSerializer.Serialize(after,AuditJson),audit.IpAddress,audit.UserAgent,audit.CorrelationId,now));
    private static RecognitionException Failure(string message,RecognitionFailureKind kind=RecognitionFailureKind.Validation)=>new(message,kind);
    private static RecognitionConsentView Map(CustomerRecognitionConsent x,DateTime now)=>new(x.Id,x.CustomerId,x.ConsentType,x.Purpose,x.GrantedUtc,x.ExpiresUtc,x.WithdrawnUtc,x.ConsentVersion,x.CapturedByUserId,x.EvidenceReference,x.IsActiveAt(now));
    private static BiometricTemplateView Map(BiometricTemplate x)=>new(x.Id,x.StoreId,x.CustomerId,x.ConsentId,x.Algorithm,x.TemplateVersion,x.Status,x.CreatedUtc,x.DisabledUtc,x.DeletedUtc,x.RetentionUntilUtc);
    private static RecognitionCandidateView Map(RecognitionCandidate x)=>new(x.Id,x.StoreId,x.PersonTrackSessionId,x.BiometricTemplateId,x.CustomerId,x.RequestId,x.Purpose,x.Confidence,x.Quality,x.SecondBestConfidence,x.Status,x.CreatedUtc,x.ReviewedUtc,x.ReviewedByUserId,x.ReviewReason);
}
